html:
{%- set company = frappe.get_doc("Company", doc.company) -%}
{%- set currency = company.default_currency -%}
{%- set s = frappe.get_doc("Zimam Settings") -%}
{%- set cur_words = {"OMR": ("ريال عماني", "بيسة"), "SAR": ("ريال سعودي", "هللة"), "AED": ("درهم إماراتي", "فلس"), "KWD": ("دينار كويتي", "فلس"), "QAR": ("ريال قطري", "درهم"), "BHD": ("دينار بحريني", "فلس"), "USD": ("دولار أمريكي", "سنت")} -%}
{%- macro words(amount) -%}
{%- set w = frappe.utils.money_in_words(amount, currency) -%}
{%- if currency in cur_words -%}{{ w.replace(currency, cur_words[currency][0]).replace("Baisa", cur_words[currency][1]).replace("Halala", cur_words[currency][1]).replace("Fils", cur_words[currency][1]).replace("Dirham", cur_words[currency][1]).replace("Cent", cur_words[currency][1]).replace("فقط.", "فقط") }}{%- else -%}{{ w }}{%- endif -%}
{%- endmacro -%}
{%- macro money(v) -%}<span dir="ltr" style="unicode-bidi:isolate;">{{ frappe.utils.fmt_money(v, currency=currency) }}</span>{%- endmacro -%}
{%- macro user(u) -%}{{ frappe.db.get_value("User", u, "full_name") if u else "" }}{%- endmacro -%}
{%- set td = 'style="border:1px solid #bbb; padding:4px 8px;"' -%}
{%- set fund_name = frappe.db.get_value("Treasury Fund", doc.fund, "fund_name") -%}
<div dir="rtl" lang="ar" style="direction:rtl; text-align:right; font-family:'Sakkal Majalla','Noto Naskh Arabic','Amiri',serif; font-size:13.5pt; line-height:1.8; padding:10px 18px;">
	<table style="width:100%; border-bottom:2px solid #5A1A30; margin-bottom:12px;">
		<tr>
			<td style="text-align:right; vertical-align:bottom; width:60%;">
				<div style="font-size:18pt; font-weight:bold; color:#5A1A30;">{{ company.company_name }}</div>
				<div style="font-size:15pt; margin-top:4px;">سند صرف</div>
			</td>
			<td style="text-align:left; vertical-align:bottom; font-size:11pt; color:#444;">
				<div>رقم السند: <b><span dir="ltr" style="unicode-bidi:isolate;">{{ doc.name }}</span></b></div>
				<div>التاريخ: <b>{{ doc.date_hijri or "" }}</b> الموافق <span dir="ltr" style="unicode-bidi:isolate;">{{ frappe.format(doc.voucher_date, {"fieldtype": "Date"}) }}</span>م</div>
				<div>المرحلة: <b>{{ doc.workflow_state or "مسودة" }}</b></div>
			</td>
		</tr>
	</table>

	<p>يُصرف للمستفيد <b>{{ doc.beneficiary_name }}</b> ({{ doc.beneficiary_type }}) مبلغًا وقدره <b>{{ money(doc.amount) }}</b> ({{ words(doc.amount) }})
	وذلك عن: <b>{{ doc.description }}</b>.</p>

	<table style="width:100%; border-collapse:collapse; font-size:12pt; margin:8px 0;">
		<tr><td {{ td }} style="border:1px solid #bbb; padding:4px 8px; width:22%; background:#faf7f2;">تصنيف المصروف</td><td {{ td }}><span dir="ltr" style="unicode-bidi:isolate;">{{ doc.expense_classification }}</span> · {{ doc.classification_name or "" }}</td>
			<td {{ td }} style="border:1px solid #bbb; padding:4px 8px; width:22%; background:#faf7f2;">طريقة الدفع</td><td {{ td }}>{{ doc.payment_method }}{% if doc.cheque_no %} — <span dir="ltr" style="unicode-bidi:isolate;">{{ doc.cheque_no }}</span>{% endif %}</td></tr>
		<tr><td {{ td }} style="border:1px solid #bbb; padding:4px 8px; background:#faf7f2;">حساب الصرف</td><td {{ td }}>{{ fund_name or doc.fund }}</td>
			<td {{ td }} style="border:1px solid #bbb; padding:4px 8px; background:#faf7f2;">المشروع / الموقع</td><td {{ td }}>{% if doc.project %}{{ frappe.db.get_value("Project", doc.project, "project_name") }}{% endif %}{% if doc.branch %} — {{ doc.branch }}{% endif %}</td></tr>
		{% if doc.due_date or doc.paid_on %}<tr><td {{ td }} style="border:1px solid #bbb; padding:4px 8px; background:#faf7f2;">الاستحقاق</td><td {{ td }}><span dir="ltr" style="unicode-bidi:isolate;">{{ frappe.format(doc.due_date, {"fieldtype": "Date"}) if doc.due_date else "" }}</span></td>
			<td {{ td }} style="border:1px solid #bbb; padding:4px 8px; background:#faf7f2;">تاريخ الدفع</td><td {{ td }}><span dir="ltr" style="unicode-bidi:isolate;">{{ frappe.format(doc.paid_on, {"fieldtype": "Date"}) if doc.paid_on else "" }}</span></td></tr>{% endif %}
	</table>

	{% if doc.allocations %}
	<table style="width:100%; border-collapse:collapse; font-size:12pt; margin-top:6px;">
		<thead><tr style="background:#5A1A30; color:#fff;"><th {{ td }}>مركز التكلفة / الوعاء المموِّل</th><th {{ td }}>المشروع</th><th {{ td }}>المبلغ</th><th {{ td }}>ملاحظة</th></tr></thead>
		<tbody>
		{% for a in doc.allocations %}
			<tr><td {{ td }}>{{ a.cost_center }}</td>
				<td {{ td }}>{% if a.project %}{{ frappe.db.get_value("Project", a.project, "project_name") }}{% endif %}</td><td {{ td }}>{{ money(a.amount) }}</td><td {{ td }}>{{ a.note or "" }}</td></tr>
		{% endfor %}
		</tbody>
	</table>
	{% endif %}

	<table style="width:100%; margin-top:28px; font-size:11.5pt; text-align:center;">
		<tr>
			<td style="width:20%; vertical-align:top;"><div style="height:36px;"></div><div style="border-top:1px solid #999; padding-top:4px;">المحاسب<br><span style="color:#555; font-size:10pt;">{{ user(doc.owner) }}</span></div></td>
			<td style="width:20%; vertical-align:top;"><div style="height:36px;"></div><div style="border-top:1px solid #999; padding-top:4px;">مدير المالية<br><span style="color:#555; font-size:10pt;">{{ user(doc.finance_reviewed_by) }}</span></div></td>
			<td style="width:20%; vertical-align:top;"><div style="height:36px;"></div><div style="border-top:1px solid #999; padding-top:4px;">معتمد الصرف<br><span style="color:#555; font-size:10pt;">{{ user(doc.approved_by) if doc.requires_ceo_approval else "—" }}</span></div></td>
			<td style="width:20%; vertical-align:top;"><div style="height:36px;"></div><div style="border-top:1px solid #999; padding-top:4px;">أمين الصندوق<br><span style="color:#555; font-size:10pt;">{{ user(doc.paid_by) }}</span></div></td>
			<td style="width:20%; vertical-align:top;"><div style="height:36px;"></div><div style="border-top:1px solid #999; padding-top:4px;">المستلم<br><span style="color:#555; font-size:10pt;">الاسم والتوقيع</span></div></td>
		</tr>
	</table>
	{% if s.voucher_note %}<div style="margin-top:14px; font-size:10pt; color:#777; text-align:center; border-top:1px dashed #ccc; padding-top:6px;">{{ s.voucher_note }}</div>{% endif %}
	<div style="font-size:9.5pt; color:#999; margin-top:6px;">قيد اليومية: <span dir="ltr" style="unicode-bidi:isolate;">{{ doc.journal_entry or "—" }}</span></div>
</div>
